function handlePavilionClick(pavilionId) {
  if (window._islandNodeDragMoved) {
    window._islandNodeDragMoved = false;
    return;
  }
  activeSelectedPavilion = pavilionId;
  document.querySelectorAll('.pavilion-node').forEach(n => n.classList.remove('is-selected'));
  const el = document.getElementById('node-' + pavilionId) || document.getElementById(pavilionId);
  if (el) el.classList.add('is-selected');

  const meta = (typeof PAVILION_META !== 'undefined') ? PAVILION_META[pavilionId] : null;
  const hasGantt = meta ? !!meta.hasGantt : (pavilionId === 'study' || pavilionId === 'dojo' || pavilionId === 'cognition' || pavilionId === 'cultivation' || String(pavilionId).startsWith('custom-'));
  const targetSubView = hasGantt ? 'gantt' : 'specialized';
  enterSecondaryWorkspace(pavilionId, targetSubView);
}

function initCanvasPanZoomAndDrag() {
  const stage = document.getElementById('island-canvas-stage');
  const canvasWorld = document.getElementById('island-world-canvas');
  if (!stage || !canvasWorld) return;

  canvasWorld.style.transformOrigin = '0 0';

  if (stage._islandGestureEngineBound) {
    bindPavilionNodesClickGuards();
    return;
  }
  stage._islandGestureEngineBound = true;

  // -------------------------------------------------------------
  // A. 鼠标滚轮 & 触控板自由缩放与漫游
  // -------------------------------------------------------------
  stage.addEventListener('wheel', (e) => {
    if (typeof currentGlobalView !== 'undefined' && currentGlobalView !== 'plan') return;
    e.preventDefault();
    e.stopPropagation();

    const rect = stage.getBoundingClientRect();
    const cursorStageX = e.clientX - rect.left;
    const cursorStageY = e.clientY - rect.top;

    // 触控板捏合 (e.ctrlKey) 或 普通鼠标垂直滚轮 -> 以光标为中心缩放
    if (e.ctrlKey || (!e.shiftKey && Math.abs(e.deltaX) < 2)) {
      const oldZoom = islandZoom || 1.0;
      const factor = e.deltaY < 0 ? 1.08 : 0.92;
      const newZoom = Math.min(3.0, Math.max(0.35, oldZoom * factor));
      const worldX = (cursorStageX - islandPanX) / oldZoom;
      const worldY = (cursorStageY - islandPanY) / oldZoom;
      islandZoom = newZoom;
      islandPanX = cursorStageX - worldX * newZoom;
      islandPanY = cursorStageY - worldY * newZoom;
    } else {
      // 触控板双指滑动平移 或 Shift+滚轮横向平移
      islandPanX -= e.deltaX || 0;
      islandPanY -= e.deltaY || 0;
    }
    applyIslandTransform();
    if (typeof bindPavilionNodesClickGuards === 'function') bindPavilionNodesClickGuards();
  }, { passive: false });

  // -------------------------------------------------------------
  // B. 现代统一 Pointer 引擎：精准支持鼠标拖拽、触屏单指平移、双指自由捏合缩放、节点卡片拖拽
  // -------------------------------------------------------------
  const activePointers = new Map();
  let pinchStartDist = 0;
  let pinchStartZoom = 1.0;
  let pinchPivotWorldX = 0;
  let pinchPivotWorldY = 0;
  let isPinching = false;
  let isPanning = false;
  let panStartX = 0;
  let panStartY = 0;
  let panInitialX = 0;
  let panInitialY = 0;

  let activeDragNode = null;
  let dragNodeStartX = 0;
  let dragNodeStartY = 0;
  let dragNodeInitLeft = 0;
  let dragNodeInitTop = 0;
  let dragNodeHasMoved = false;

  const isInteractiveTarget = (t) => {
    if (!t) return false;
    return !!t.closest('button, input, select, textarea, .a-my-island-plugin-launcher, .a-my-island-graph-toolbar, .hud-profile-container, .parent-bounty-billboard, .a-my-island-island-settings-panel, .a-my-island-work-navigation-dock');
  };

  stage.addEventListener('pointerdown', (e) => {
    if (typeof currentGlobalView !== 'undefined' && currentGlobalView !== 'plan') return;
    if (isInteractiveTarget(e.target)) return;

    activePointers.set(e.pointerId, { clientX: e.clientX, clientY: e.clientY });

    // 1. 双指触控模式 -> 启动双指自由捏合缩放
    if (activePointers.size === 2) {
      isPinching = true;
      isPanning = false;
      if (activeDragNode) {
        try { activeDragNode.releasePointerCapture(e.pointerId); } catch (_) {}
        activeDragNode.classList.remove('is-node-dragging');
        activeDragNode = null;
      }
      const pts = Array.from(activePointers.values());
      pinchStartDist = Math.hypot(pts[1].clientX - pts[0].clientX, pts[1].clientY - pts[0].clientY);
      pinchStartZoom = islandZoom || 1.0;

      const rect = stage.getBoundingClientRect();
      const midStageX = (pts[0].clientX + pts[1].clientX) / 2 - rect.left;
      const midStageY = (pts[0].clientY + pts[1].clientY) / 2 - rect.top;
      pinchPivotWorldX = (midStageX - islandPanX) / pinchStartZoom;
      pinchPivotWorldY = (midStageY - islandPanY) / pinchStartZoom;
      return;
    }

    // 2. 单指触控 / 鼠标点击
    if (activePointers.size === 1) {
      const node = e.target.closest('.pavilion-node');
      if (node) {
        activeDragNode = node;
        dragNodeHasMoved = false;
        dragNodeStartX = e.clientX;
        dragNodeStartY = e.clientY;
        dragNodeInitLeft = node.offsetLeft;
        dragNodeInitTop = node.offsetTop;
        node.classList.add('is-node-dragging');
        try { node.setPointerCapture(e.pointerId); } catch (_) {}
        return;
      }

      // 点击空白背景 -> 启动画布平移
      isPanning = true;
      isPinching = false;
      panStartX = e.clientX;
      panStartY = e.clientY;
      panInitialX = islandPanX;
      panInitialY = islandPanY;
      stage.classList.add('is-canvas-dragging');
      try { stage.setPointerCapture(e.pointerId); } catch (_) {}
    }
  });

  const onPointerMove = (e) => {
    if (typeof currentGlobalView !== 'undefined' && currentGlobalView !== 'plan') return;
    if (!activePointers.has(e.pointerId)) return;
    activePointers.set(e.pointerId, { clientX: e.clientX, clientY: e.clientY });

    // 1. 处理双指捏合缩放
    if (isPinching && activePointers.size >= 2) {
      const pts = Array.from(activePointers.values());
      const currentDist = Math.hypot(pts[1].clientX - pts[0].clientX, pts[1].clientY - pts[0].clientY);
      if (pinchStartDist > 0) {
        const factor = currentDist / pinchStartDist;
        const newZoom = Math.min(3.0, Math.max(0.35, pinchStartZoom * factor));
        const rect = stage.getBoundingClientRect();
        const currentMidStageX = (pts[0].clientX + pts[1].clientX) / 2 - rect.left;
        const currentMidStageY = (pts[0].clientY + pts[1].clientY) / 2 - rect.top;
        islandZoom = newZoom;
        islandPanX = currentMidStageX - pinchPivotWorldX * newZoom;
        islandPanY = currentMidStageY - pinchPivotWorldY * newZoom;
        applyIslandTransform();
        if (typeof bindPavilionNodesClickGuards === 'function') bindPavilionNodesClickGuards();
      }
      return;
    }

    // 2. 处理场馆节点卡片拖拽
    if (activeDragNode && activePointers.size === 1) {
      const dx = (e.clientX - dragNodeStartX) / islandZoom;
      const dy = (e.clientY - dragNodeStartY) / islandZoom;
      if (!dragNodeHasMoved && (Math.abs(dx) > 3 || Math.abs(dy) > 3)) {
        dragNodeHasMoved = true;
        activeDragNode._dragMoved = true;
        window._islandNodeDragMoved = true;
      }
      if (dragNodeHasMoved) {
        activeDragNode.style.left = (dragNodeInitLeft + dx) + 'px';
        activeDragNode.style.top = (dragNodeInitTop + dy) + 'px';
        updateIslandMinimap();
      }
      return;
    }

    // 3. 处理单指/鼠标空白背景平移漫游
    if (isPanning && activePointers.size === 1) {
      const dx = e.clientX - panStartX;
      const dy = e.clientY - panStartY;
      islandPanX = panInitialX + dx;
      islandPanY = panInitialY + dy;
      applyIslandTransform();
      if (typeof bindPavilionNodesClickGuards === 'function') bindPavilionNodesClickGuards();
      return;
    }
  };

  const onPointerUp = (e) => {
    activePointers.delete(e.pointerId);

    if (activeDragNode) {
      const node = activeDragNode;
      activeDragNode = null;
      try { node.releasePointerCapture(e.pointerId); } catch (_) {}
      node.classList.remove('is-node-dragging');
      if (dragNodeHasMoved) {
        node._dragMoved = true;
        window._islandNodeDragMoved = true;
        setTimeout(() => {
          node._dragMoved = false;
          window._islandNodeDragMoved = false;
        }, 220);
      }
    }

    if (activePointers.size < 2 && isPinching) {
      isPinching = false;
    }
    if (activePointers.size === 0) {
      isPanning = false;
      try { stage.releasePointerCapture(e.pointerId); } catch (_) {}
      stage.classList.remove('is-canvas-dragging');
    }
  };

  stage.addEventListener('pointermove', onPointerMove);
  window.addEventListener('pointermove', onPointerMove);
  stage.addEventListener('pointerup', onPointerUp);
  stage.addEventListener('pointercancel', onPointerUp);
  window.addEventListener('pointerup', onPointerUp);

  // -------------------------------------------------------------
  // C. 移动端原生 TouchEvents 完整支持：单指平移、双指双向缩放、节点拖拽
  // -------------------------------------------------------------
  let touchPinchStartDist = 0;
  let touchPinchStartZoom = 1.0;
  let touchPinchPivotWorldX = 0;
  let touchPinchPivotWorldY = 0;
  let isTouchPinching = false;
  let isTouchPanning = false;
  let touchPanStartX = 0;
  let touchPanStartY = 0;
  let touchPanInitialX = 0;
  let touchPanInitialY = 0;
  let activeTouchNode = null;
  let touchNodeStartX = 0;
  let touchNodeStartY = 0;
  let touchNodeInitLeft = 0;
  let touchNodeInitTop = 0;
  let touchNodeHasMoved = false;

  stage.addEventListener('touchstart', (e) => {
    if (typeof currentGlobalView !== 'undefined' && currentGlobalView !== 'plan') return;
    if (isInteractiveTarget(e.target)) return;

    if (e.touches.length === 2) {
      isTouchPinching = true;
      isTouchPanning = false;
      if (activeTouchNode) {
        activeTouchNode.classList.remove('is-node-dragging');
        activeTouchNode = null;
      }
      const t1 = e.touches[0];
      const t2 = e.touches[1];
      touchPinchStartDist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
      touchPinchStartZoom = islandZoom || 1.0;
      const rect = stage.getBoundingClientRect();
      const midX = (t1.clientX + t2.clientX) / 2 - rect.left;
      const midY = (t1.clientY + t2.clientY) / 2 - rect.top;
      touchPinchPivotWorldX = (midX - islandPanX) / touchPinchStartZoom;
      touchPinchPivotWorldY = (midY - islandPanY) / touchPinchStartZoom;
      return;
    }

    if (e.touches.length === 1) {
      const node = e.target.closest('.pavilion-node');
      if (node) {
        activeTouchNode = node;
        touchNodeHasMoved = false;
        touchNodeStartX = e.touches[0].clientX;
        touchNodeStartY = e.touches[0].clientY;
        touchNodeInitLeft = node.offsetLeft;
        touchNodeInitTop = node.offsetTop;
        node.classList.add('is-node-dragging');
        return;
      }

      isTouchPanning = true;
      isTouchPinching = false;
      touchPanStartX = e.touches[0].clientX;
      touchPanStartY = e.touches[0].clientY;
      touchPanInitialX = islandPanX;
      touchPanInitialY = islandPanY;
      stage.classList.add('is-canvas-dragging');
    }
  }, { passive: true });

  stage.addEventListener('touchmove', (e) => {
    if (typeof currentGlobalView !== 'undefined' && currentGlobalView !== 'plan') return;
    if (!isTouchPinching && !isTouchPanning && !activeTouchNode) return;

    // 1. 双指触控捏合缩放
    if (isTouchPinching && e.touches.length === 2) {
      if (e.cancelable) e.preventDefault();
      const t1 = e.touches[0];
      const t2 = e.touches[1];
      const currentDist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
      if (touchPinchStartDist > 0) {
        const factor = currentDist / touchPinchStartDist;
        const newZoom = Math.min(3.0, Math.max(0.35, touchPinchStartZoom * factor));
        const rect = stage.getBoundingClientRect();
        const midX = (t1.clientX + t2.clientX) / 2 - rect.left;
        const midY = (t1.clientY + t2.clientY) / 2 - rect.top;
        islandZoom = newZoom;
        islandPanX = midX - touchPinchPivotWorldX * newZoom;
        islandPanY = midY - touchPinchPivotWorldY * newZoom;
        applyIslandTransform();
      }
      return;
    }

    // 2. 节点拖拽
    if (activeTouchNode && e.touches.length === 1) {
      if (e.cancelable) e.preventDefault();
      const dx = (e.touches[0].clientX - touchNodeStartX) / islandZoom;
      const dy = (e.touches[0].clientY - touchNodeStartY) / islandZoom;
      if (!touchNodeHasMoved && (Math.abs(dx) > 3 || Math.abs(dy) > 3)) {
        touchNodeHasMoved = true;
        activeTouchNode._dragMoved = true;
        window._islandNodeDragMoved = true;
      }
      if (touchNodeHasMoved) {
        activeTouchNode.style.left = (touchNodeInitLeft + dx) + 'px';
        activeTouchNode.style.top = (touchNodeInitTop + dy) + 'px';
        updateIslandMinimap();
      }
      return;
    }

    // 3. 画布单指平移
    if (isTouchPanning && e.touches.length === 1) {
      if (e.cancelable) e.preventDefault();
      const dx = e.touches[0].clientX - touchPanStartX;
      const dy = e.touches[0].clientY - touchPanStartY;
      islandPanX = touchPanInitialX + dx;
      islandPanY = touchPanInitialY + dy;
      applyIslandTransform();
      return;
    }
  }, { passive: false });

  const endTouch = () => {
    if (activeTouchNode) {
      const node = activeTouchNode;
      activeTouchNode = null;
      node.classList.remove('is-node-dragging');
      if (touchNodeHasMoved) {
        node._dragMoved = true;
        window._islandNodeDragMoved = true;
        setTimeout(() => {
          node._dragMoved = false;
          window._islandNodeDragMoved = false;
        }, 220);
      }
    }
    isTouchPinching = false;
    isTouchPanning = false;
    stage.classList.remove('is-canvas-dragging');
  };

  stage.addEventListener('touchend', endTouch, { passive: true });
  stage.addEventListener('touchcancel', endTouch, { passive: true });

  // -------------------------------------------------------------
  // D. 捕获阶段防御：严防节点拖拽结束误触发 handlePavilionClick 路由
  // -------------------------------------------------------------
  stage.addEventListener('click', (e) => {
    if (window._islandNodeDragMoved && e.target.closest('.pavilion-node')) {
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
      window._islandNodeDragMoved = false;
      return false;
    }
  }, true);

  bindPavilionNodesClickGuards();
}

function bindPavilionNodesClickGuards() {
  document.querySelectorAll('.pavilion-node').forEach(node => {
    if (node._clickGuardBound) return;
    node._clickGuardBound = true;
    node.addEventListener('click', (e) => {
      if (node._dragMoved || window._islandNodeDragMoved) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        node._dragMoved = false;
        window._islandNodeDragMoved = false;
        return false;
      }
    }, true);
  });
}

function initNodeDragging(node) {
  bindPavilionNodesClickGuards();
}

