        projectTypeLabel: '校史馆 · 学科学业攻坚',
        projectName: '小学数学口算达标与逆向思维训练',
        metrics: [
          { name: '单元口算正确率', target: '≥ 98%', actual: '100% 达成' },
          { name: '进退位心算提分', target: 'Delta +15 分', actual: '超额达标' }
        ],
        proof: '📷 目标交付物手稿照片已归档',
        issuer: '校史馆学科教研组 · 审验',
        desc: '通过口算正确率与心算通关指标考核，交付实训手稿存证，达成阶段突破。'
      });
