  const m = typeMap[type] || typeMap.task;
  const title = prompt('请输入新建【' + m.name + '】模块标题：', m.name + '攻坚切片 ' + tertiaryCardIndex);
  if (!title) return;

  const world = document.getElementById('tertiary-canvas-world');
