function updateDayCarousel() {
  const allCards = document.querySelectorAll('.exec-card-deck .exec-task-card');
  const dotsWrap = document.getElementById('exec-carousel-dots');
  const emptyPlaceholder = document.getElementById('day-deck-empty-placeholder');

  if (allCards.length === 0) {
    totalDayCards = 0;
    currentDayCardIndex = 0;
    if (dotsWrap) dotsWrap.style.display = 'none';
    if (emptyPlaceholder) emptyPlaceholder.style.display = 'flex';
    return;
  }
  if (emptyPlaceholder) emptyPlaceholder.style.display = 'none';
  if (dotsWrap) dotsWrap.style.display = 'flex';
  totalDayCards = allCards.length;
  currentDayCardIndex = Math.max(0, Math.min(currentDayCardIndex, totalDayCards - 1));
  window.currentDayCardIndex = currentDayCardIndex;
  const cards = allCards;
  const dots = document.querySelectorAll('.exec-carousel-pagination .pagination-dot-pill');

  cards.forEach((card, idx) => {
    card.classList.remove('card-active', 'card-prev', 'card-next', 'card-far-prev', 'card-far-next');
    let offset = idx - currentDayCardIndex;
    if (offset > 2) offset -= totalDayCards;
    if (offset < -2) offset += totalDayCards;

    if (offset === 0) {
      card.classList.add('card-active');
    } else if (offset === -1) {
      card.classList.add('card-prev');
    } else if (offset === 1) {
      card.classList.add('card-next');
    } else if (offset <= -2) {
      card.classList.add('card-far-prev');
    } else if (offset >= 2) {
      card.classList.add('card-far-next');
    }
  });

  dots.forEach((dot, idx) => {
    dot.classList.toggle('active', idx === currentDayCardIndex);
  });
}

function nextDayCard() {
  if (totalDayCards <= 0) return;
  currentDayCardIndex = (currentDayCardIndex + 1) % totalDayCards;
  updateDayCarousel();
}

function prevDayCard() {
  if (totalDayCards <= 0) return;
  currentDayCardIndex = (currentDayCardIndex - 1 + totalDayCards) % totalDayCards;
  updateDayCarousel();
}

function goToDayCard(index) {
  currentDayCardIndex = index;
  updateDayCarousel();
}

function setupCarouselGestures() {
  const stage = document.getElementById('exec-carousel-stage');
  const deck = document.getElementById('day-card-deck');
  if (!stage || !deck) return;
  if (stage._carouselGesturesBound) return;
  stage._carouselGesturesBound = true;

  let startX = 0;
  let startY = 0;
  let currentDeltaX = 0;
  let isDragging = false;
  let isHorizontalGesture = false;
  let isVerticalScroll = false;
  let pointerId = null;

  const resetDeckTransform = (animate = true) => {
    if (animate) {
      deck.style.transition = 'transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1)';
    } else {
      deck.style.transition = 'none';
    }
    deck.style.transform = '';
  };

  const handleStart = (clientX, clientY, pId = null) => {
    startX = clientX;
    startY = clientY;
    currentDeltaX = 0;
    isDragging = true;
    isHorizontalGesture = false;
    isVerticalScroll = false;
    pointerId = pId;
    resetDeckTransform(false);
  };

  const handleMove = (clientX, clientY, e) => {
    if (!isDragging) return;
    const dx = clientX - startX;
    const dy = clientY - startY;

    if (!isHorizontalGesture && !isVerticalScroll) {
      if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 6) {
        isVerticalScroll = true;
        return;
      }
      if (Math.abs(dx) > 6 && Math.abs(dx) > Math.abs(dy)) {
        isHorizontalGesture = true;
      }
    }

    if (isVerticalScroll) return;

    if (isHorizontalGesture) {
      if (e && e.cancelable) e.preventDefault();
      currentDeltaX = dx;
      const resistance = 0.65;
      const visualX = dx * resistance;
      deck.style.transition = 'none';
      deck.style.transform = `translateX(${visualX}px)`;
    }
  };

  const handleEnd = () => {
    if (!isDragging) return;
    isDragging = false;
    const deltaX = currentDeltaX;
    currentDeltaX = 0;

    resetDeckTransform(true);

    if (isHorizontalGesture && Math.abs(deltaX) > 35) {
      if (deltaX < 0) {
        nextDayCard();
      } else {
        prevDayCard();
      }
    }
    isHorizontalGesture = false;
    isVerticalScroll = false;
    pointerId = null;
  };

  // 移动端 Touch 事件
  stage.addEventListener('touchstart', (e) => {
    if (e.touches.length === 1) {
      if (e.target.closest('button, input, select, textarea, a, .card-graphic-pill')) return;
      handleStart(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, { passive: true });

  stage.addEventListener('touchmove', (e) => {
    if (e.touches.length === 1) {
      handleMove(e.touches[0].clientX, e.touches[0].clientY, e);
    }
  }, { passive: false });

  stage.addEventListener('touchend', () => {
    handleEnd();
  }, { passive: true });

  stage.addEventListener('touchcancel', () => {
    handleEnd();
  }, { passive: true });

  // 桌面端 Pointer/Mouse 事件
  stage.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'touch') return;
    if (e.target.closest('button, input, select, textarea, a, .card-graphic-pill')) return;
    handleStart(e.clientX, e.clientY, e.pointerId);
    try { stage.setPointerCapture(e.pointerId); } catch (_) {}
  });

  const onPointerMove = (e) => {
    if (e.pointerType === 'touch') return;
    if (isDragging && (pointerId === e.pointerId || pointerId === null)) {
      handleMove(e.clientX, e.clientY, e);
    }
  };

  const onPointerUp = (e) => {
    if (e.pointerType === 'touch') return;
    if (pointerId === e.pointerId || pointerId === null) {
      try { stage.releasePointerCapture(e.pointerId); } catch (_) {}
      handleEnd();
    }
  };

  stage.addEventListener('pointermove', onPointerMove);
  window.addEventListener('pointermove', onPointerMove);
  stage.addEventListener('pointerup', onPointerUp);
  stage.addEventListener('pointercancel', onPointerUp);
  window.addEventListener('pointerup', onPointerUp);
}

