function(){
  const amountEl=document.getElementById('treasury-tx-amount-input');if(!amountEl)return false;
  const amount=Number(amountEl.value),cents=Math.round(amount*100),treasury=window.TREASURY_STATE,type=treasury.currentRecordType||'income';
  if(!Number.isFinite(amount)||amount<=0||!Number.isSafeInteger(cents)||Math.abs(amount*100-cents)>1e-7){showIslandToast('金额必须为正数，最多保留两位小数');return false;}
  if(type==='expense'&&cents>Math.round(treasury.totalBalance*100)){showIslandToast('余额不足，不能透支');return false;}
  const note=document.getElementById('treasury-tx-desc-input')?.value.trim()||'未填写说明',proof=document.getElementById('treasury-tx-proof-input')?.value.trim()||'未提供凭据说明';
  treasury.totalBalance=Math.round((treasury.totalBalance*100+(type==='income'?cents:-cents)))/100;
  const field=type==='income'?'totalIncome':'totalExpense';treasury[field]=Math.round(treasury[field]*100+cents)/100;
  const record={id:domainId('transaction'),time:new Date().toISOString(),date:domainDate(),type,category:document.getElementById('treasury-tx-category-select')?.value||'其他',amount:type==='income'?amount:-amount,balanceAfter:treasury.totalBalance,note,proof};
  treasury.ledger.unshift(record);amountEl.value='';const desc=document.getElementById('treasury-tx-desc-input');if(desc)desc.value='';updateTreasuryLiveDOM();
  domainEvent('treasury.recorded',record.id,(type==='income'?'零用金收入':'零用金支出')+' ¥'+amount.toFixed(2)+' · '+note);showIslandToast('真实收支已记入账本');return record;
}

